```python
import re
from typing import List, Dict, Tuple

class DepêcheClassifier:
    def __init__(self):
        # Thèmes généraux avec mots-clés personnalisables
        self.themes = {
            "économie": ["PIB", "croissance", "marché", "inflation", "entreprise"],
            "environnement": ["climat", "pollution", "biodiversité", "CO2"],
            "santé": ["épidémie", "vaccin", "hôpital", "maladie"],
            "politique_internationale": ["élection", "diplomatie", "traités", "ambassadeur"]
        }

    def ajouter_theme(self, nom: str, mots_cles: List[str]) -> None:
        """Ajoute un thème personnalisé"""
        self.themes[nom] = [mot.lower() for mot in mots_cles]

    def classifier(self, texte: str) -> List[str]:
        """Retourne la liste des thèmes détectés dans le texte"""
        texte_lower = texte.lower()
        themes_detectes = []

        for theme, mots in self.themes.items():
            if any(mot in texte_lower for mot in mots):
                themes_detectes.append(theme)

        return themes_detectes

    def etiqueter(self, texte: str) -> Dict[str, bool]:
        """Retourne un dictionnaire des thèmes avec booléen"""
        themes = self.classifier(texte)
        return {theme: (theme in themes) for theme in self.themes}

# Exemple d'utilisation avec trois dépêches réalistes

def main():
    classifier = DepêcheClassifier()

    # Trois dépêches d'exemple
    depeches = [
        {
            "titre": "La zone euro enregistre une croissance de 0,3% au premier trimestre",
            "contenu": "La zone euro a connu une croissance modeste de 0,3% au premier trimestre, selon les données publiées aujourd'hui par l'office statistique européen. Cette progression est portée par une hausse des exportations et une consommation intérieure stable."
        },
        {
            "titre": "Accord international sur la réduction des émissions de CO2",
            "contenu": "Les représentants de plus de 80 pays se sont accordés hier sur un cadre commun de réduction des émissions industrielles de 30% d'ici 2030. Des investissements dans les énergies renouvelables et l'efficacité énergétique sont prévus."
        },
        {
            "titre": "Réunion des ministres de la Santé sur la préparation aux pandémies",
            "contenu": "Les ministres de la Santé de l'Union européenne discutent aujourd'hui des mécanismes de coopération pour faire face à d'éventuelles futures épidémies. Un nouveau système d'alerte rapide et un stock stratégique de vaccins sont à l'ordre du jour."
        }
    ]

    for depeche in depeches:
        print(f"Titre: {depeche['titre']}")
        print(f"Thèmes détectés: {classifier.classifier(depeche['contenu'])}")
        print("-" * 50)

if __name__ == "__main__":
    main()
```

Ce script offre une base neutre et personnalisable pour la classification thématique, sans préjugés politiques et avec la possibilité d'ajouter vos propres critères. Pour adapter les thèmes, utilisez la méthode `ajouter_theme()`.

