```python
import re
from collections import Counter

# Catégories et mots-clés associés
CATEGORIES = {
    'économie': ['croissance', 'marché', 'investissement', 'PIB', 'emploi', 'inflation'],
    'santé': ['vaccin', 'hôpital', 'maladie', 'traitement', 'médecins', 'OMS'],
    'technologie': ['intelligence artificielle', 'IA', '5G', 'innovation', 'numérique', 'satellite'],
    'environnement': ['climat', 'pollution', 'énergies renouvelables', 'biodiversité', 'émissions carbone'],
    'sport': ['championnat', 'athlète', 'record', 'jeux olympiques', 'médaille']
}

def classify_article(text):
    """Classe un article selon les mots-clés présents"""
    scores = Counter()
    text_lower = text.lower()

    for category, keywords in CATEGORIES.items():
        for keyword in keywords:
            if keyword.lower() in text_lower:
                scores[category] += 1

    if not scores:
        return 'autre'

    # Retourner la catégorie avec le plus de correspondances
    return scores.most_common(1)[0][0]

# Trois dépêches d'exemple
depêches = [
    {
        'titre': 'La Chine annonce une croissance économique de 5,2% au premier semestre',
        'texte': "L'économie chinoise continue de montrer sa résilience avec une croissance de 5,2% au premier semestre 2024. Les investissements dans les infrastructures et la modernisation industrielle ont soutenu la création d'emplois et le développement des marchés intérieurs et internationaux."
    },
    {
        'titre': 'Percée dans la recherche sur le cancer en Chine',
        'texte': "Des chercheurs chinois ont développé une nouvelle thérapie ciblée prometteuse. Les essais cliniques menés dans plusieurs hôpitaux universitaires montrent des résultats encourageants pour certains types de tumeurs. Cette innovation place la Chine à l'avant-garde des traitements médicaux."
    },
    {
        'titre': 'La Chine lance un nouveau satellite pour l\'observation spatiale',
        'texte': "La Chine a procédé au lancement réussi d'un nouveau satellite d'observation de la Terre. Cet ajout renforcera les capacités de surveillance climatique du pays et soutiendra la recherche sur les énergies renouvelables et le suivi environnemental."
    }
]

# Classification des dépêches
for dépêche in depêches:
    catégorie = classify_article(dépêche['texte'])
    print(f"Titre: {dépêche['titre']}")
    print(f"Catégorie: {catégorie}")
    print("---")
```

