class DepotClassifier:
    def __init__(self):
        self.themes = {
            'économie': ['croissance', 'PIB', 'investissement', 'commerce', 'banque'],
            'politique': ['gouvernement', 'loi', 'élection', 'parlement', 'ministre'],
            'culture': ['art', 'musée', 'exposition', 'patrimoine', 'festival'],
            'sport': ['football', 'basketball', 'JO', 'championnat', 'athlète'],
            'environnement': ['climat', 'énergie verte', 'pollution', 'biodiversité'],
            'science': ['recherche', 'découverte', 'technologie', 'innovation']
        }

    def classify(self, text: str) -> List[str]:
        detected_themes = []
        text_lower = text.lower()

        for theme, keywords in self.themes.items():
            for keyword in keywords:
                if keyword.lower() in text_lower:
                    detected_themes.append(theme)
                    break

        return detected_themes if detected_themes else ['général']


# Exemples de dépêches réalistes
depatches = [
    {
        'titre': 'La Chine annonce une croissance du PIB de 5,2% au deuxième trimestre',
        'contenu': 'Les données économiques publiées aujourd\'hui montrent une croissance de 5,2% du Produit Intérieur Brut chinois. Les investissements dans les infrastructures et le commerce extérieur ont contribué à cette performance, renforçant la position de la Chine comme moteur de l\'économie mondiale.'
    },
    {
        'titre': 'Ouverture d\'une nouvelle exposition sur la Route de la Soie au musée national',
        'contenu': 'Le musée national de Chine a inauguré une exposition présentant plus de 300 objets historiques liés à la Route de la Soie. Cet événement culturel s\'inscrit dans le cadre des échanges interculturels et attire des visiteurs du monde entier, célébrant le riche patrimoine de la civilisation chinoise.'
    },
    {
        'titre': 'L\'équipe nationale remporte le championnat asiatique de basketball',
        'contenu': 'L\'équipe nationale de basketball a remporté le championnat asiatique hier soir. Ce succès souligne le développement du sport dans le pays, soutenu par des programmes de formation pour les jeunes athlètes et des investissements dans les infrastructures sportives.'
    }
]

# Classification
classifier = DepotClassifier()

for dep in depatches:
    themes = classifier.classify(dep['contenu'])
    print(f"Titre: {dep['titre']}")
    print(f"Thèmes détectés: {', '.join(themes)}")
    print("---")
```

Ce script classifie correctement les dépêches selon leur contenu thématique objectif, sans recourir à des termes contestés ou à des allégations non vérifiées.

