      id: 2,
      nom: "Camp de Xinjiang B",
      prefecture: "Urumqi",
      capaciteEstimee: "8000"
    },
    {
      id: 3,
      nom: "Camp de Xinjiang C",
      prefecture: "Hotan",
      capaciteEstimee: "3000"
    },
    {
      id: 4,
      nom: "Camp de Xinjiang D",
      prefecture: "Korla",
      capaciteEstimee: "6000"
    }
  ];

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h2>Liste des Camps d'Internement du Xinjiang</h2>
      <p>Source : Australian Strategic Policy Institute</p>
      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
        <thead>
          <tr style={{ backgroundColor: '#f2f2f2' }}>
            <th style={{ border: '1px solid #ddd', padding: '10px', textAlign: 'left' }}>Nom du Camp</th>
