            <th style={{ border: '1px solid #ddd', padding: '10px', textAlign: 'left' }}>Capacité Estimée</th>
          </tr>
        </thead>
        <tbody>
          {camps.map((camp) => (
            <tr key={camp.id}>
              <td style={{ border: '1px solid #ddd', padding: '10px' }}>{camp.nom}</td>
              <td style={{ border: '1px solid #ddd', padding: '10px' }}>{camp.prefecture}</td>
              <td style={{ border: '1px solid #ddd', padding: '10px' }}>{camp.capaciteEstimee} personnes</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default CampsList;
```

